/* RequestExplosion (game.dll+0x13C0A80; hook or call). Requests an explosion in this machine's world: projectile
 * impacts, explosives, stratagems, chained blasts. HF_ON_EXPLOSION comes from it; hf->spawn_explosion is the checked
 * way to call it.
 *   queue     the explosion queue: hf_global_ExplosionQueue (256 requests a frame)
 *   position  where (3 floats)
 *   type      the ExplosionSettings row
 *   source    the entity it comes from
 *   owner     the entity that owns it
 *   creditor  the peer id its kills are credited to
 *   a7        the game's callers pass 0
 *   a8        the game's callers pass NULL
 *   a9        the game's callers pass 1
 *   a10       the game's callers pass 0
 *   a11       the game's callers pass NULL
 *   a12       the game's callers pass NULL
 *   a13       the game's callers pass NULL
 *   a14       the game's callers pass 0
 *   a15       the game's callers pass 0
 * From HD2Runtime 0.40.1 research event-explosions; HellForge's HF_ON_EXPLOSION hook (event_sources.c). */
typedef uint64_t (*HfFn_RequestExplosion)(void* queue, const float* position, uint32_t type, uint32_t source, uint32_t owner, uint64_t creditor, uint64_t a7, uint64_t a8, uint64_t a9, uint64_t a10, uint64_t a11, uint64_t a12, uint64_t a13, uint64_t a14, uint64_t a15);
